        item = Order(name, quantity, price)
        self.items.append(item)

    def get_items(self):
        return self.items

class PriceCalculator:
    @staticmethod
    def calculate_total(order_manager: OrderQuantityManager) -> float:
        total = 0
        for item in order_manager.get_items():
            total += item.quantity * item.price
        return total
